planChart.mermaid:
flowchart LR
  A([draw runs]) --> B{state is title}
  B -- yes --> C[[drawTitle]]
  C --> D{space pressed}
  D -- yes --> E[state = play]
  D -- no --> Z([end of frame])
  E --> Z
  B -- no --> F{state is play}
  F -- yes --> G[[updateGame]]
  G --> H{player dead}
  H -- yes --> I[state = gameover]
  H -- no --> Z
  I --> Z
  F -- no --> M{state is gameover}
  M -- yes --> J[[drawGameOver]]
  M -- no --> Z
  J --> K{r pressed}
  K -- yes --> L[state = title]
  K -- no --> Z
  L --> Z
